import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/instances")
public class InstanceController {

    private final InstanceService instanceService;

    public InstanceController(InstanceService instanceService) {
        this.instanceService = instanceService;
    }

    @PostMapping
    public ApiResponse<Instance> create(@RequestBody CreateInstanceRequest request) {
        Instance instance = instanceService.create(request);
        return ApiResponse.success("注册成功", instance);
    }

    @GetMapping
    public ApiResponse<List<Instance>> list(@RequestParam(value = "dbType", required = false) String dbType,
                                            @RequestParam(value = "groupId", required = false) Long groupId) {
        return ApiResponse.success(instanceService.list(dbType, groupId));
    }

    @GetMapping("/{id}")
    public ApiResponse<Instance> detail(@PathVariable("id") Long id) {
        Instance instance = instanceService.getById(id);
        if (instance == null) {
            return ApiResponse.error(404, "实例不存在");
        }
        return ApiResponse.success(instance);
    }

    @PutMapping("/{id}")
    public ApiResponse<Instance> update(@PathVariable("id") Long id, @RequestBody UpdateInstanceRequest request) {
        Instance instance = instanceService.update(id, request);
        if (instance == null) {
            return ApiResponse.error(404, "实例不存在");
        }
        return ApiResponse.success("更新成功", instance);
    }

    @DeleteMapping("/{id}")
    public ApiResponse<Void> delete(@PathVariable("id") Long id) {
        if (!instanceService.delete(id)) {
            return ApiResponse.error(404, "实例不存在");
        }
        return ApiResponse.success("删除成功", null);
    }

    @PostMapping("/{id}/ping")
    public ApiResponse<Map<String, Object>> ping(@PathVariable("id") Long id) {
        Map<String, Object> result = instanceService.ping(id);
        if (result == null) {
            return ApiResponse.error(404, "实例不存在");
        }
        return ApiResponse.success("连通测试完成", result);
    }
}

package com.dbconsole.platform.dto;

public class ApiResponse<T> {

    private int code;
    private String message;
    private T data;

    public ApiResponse() {
    }

    public ApiResponse(int code, String message, T data) {
        this.code = code;
        this.message = message;
        this.data = data;
    }

    public static <T> ApiResponse<T> success(T data) {
        return new ApiResponse<>(200, "success", data);
    }

    public static <T> ApiResponse<T> success(String message, T data) {
        return new ApiResponse<>(200, message, data);
    }

    public static <T> ApiResponse<T> error(int code, String message) {
        return new ApiResponse<>(code, message, null);
    }

    public int getCode() {
        return code;
    }

    public void setCode(int code) {
        this.code = code;
    }

    public String getMessage() {
        return message;
    }

    public void setMessage(String message) {
        this.message = message;
    }

    public T getData() {
        return data;
    }

    public void setData(T data) {
        this.data = data;
    }
}

